{
  "name": "@skythelight/opencode-plugin-dashboard",
  "version": "0.1.1",
  "description": "A web-based dashboard for managing OpenCode plugins: view, toggle, add, remove, validate, and hot-reload your opencode.json — plus live theming.",
  "license": "MIT",
  "type": "module",
  "bin": {
    "opencode-plugin-dashboard": "bin/cli.js"
  },
  "main": "src/server.js",
  "files": [
    "bin",
    "src",
    "public",
    "start.bat",
    "README.md",
    "LICENSE"
  ],
  "engines": {
    "node": ">=18",
    "bun": ">=1.0"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "dashboard",
    "plugins",
    "manager",
    "config"
  ],
  "scripts": {
    "start": "node bin/cli.js"
  },
  "dependencies": {}
}
